			'import { Stack } from \'@atlaskit/primitives/compiled/stack\';\nimport { Text } from \'@atlaskit/primitives/compiled/text\';\nimport { token } from \'@atlaskit/tokens\';\nimport { Card } from \'@atlassian/card\';\nimport { CardBody } from \'@atlassian/card/card-body\';\nimport { CardContent } from \'@atlassian/card/card-content\';\nimport { CardFooter } from \'@atlassian/card/card-footer\';\nimport { CardMedia } from \'@atlassian/card/card-media\';\nimport { CardPrimaryContent } from \'@atlassian/card/card-primary-content\';\nfunction MediaCard({ position }: { position: \'top\' | \'bottom\' }): React.JSX.Element {\n\tconst media = (\n\t\t<CardMedia position={position}>\n\t\t\t<svg\n\t\t\t\tviewBox="0 0 640 220"\n\t\t\t\twidth="100%"\n\t\t\t\theight="140"\n\t\t\t\trole="img"\n\t\t\t\taria-label="Project dashboard showing milestones and progress"\n\t\t\t\tpreserveAspectRatio="xMidYMid slice"\n\t\t\t>\n\t\t\t\t<rect width="640" height="220" fill={token(\'color.background.neutral\')} />\n\t\t\t\t<rect x="24" y="24" width="128" height="172" rx="8" fill={token(\'elevation.surface\')} />\n\t\t\t\t<rect\n\t\t\t\t\tx="42"\n\t\t\t\t\ty="44"\n\t\t\t\t\twidth="74"\n\t\t\t\t\theight="10"\n\t\t\t\t\trx="5"\n\t\t\t\t\tfill={token(\'color.background.neutral.bold\')}\n\t\t\t\t/>\n\t\t\t\t<rect\n\t\t\t\t\tx="42"\n\t\t\t\t\ty="70"\n\t\t\t\t\twidth="92"\n\t\t\t\t\theight="7"\n\t\t\t\t\trx="3.5"\n\t\t\t\t\tfill={token(\'color.background.neutral\')}\n\t\t\t\t/>\n\t\t\t\t<rect\n\t\t\t\t\tx="42"\n\t\t\t\t\ty="90"\n\t\t\t\t\twidth="78"\n\t\t\t\t\theight="7"\n\t\t\t\t\trx="3.5"\n\t\t\t\t\tfill={token(\'color.background.neutral\')}\n\t\t\t\t/>\n\t\t\t\t<rect\n\t\t\t\t\tx="42"\n\t\t\t\t\ty="110"\n\t\t\t\t\twidth="86"\n\t\t\t\t\theight="7"\n\t\t\t\t\trx="3.5"\n\t\t\t\t\tfill={token(\'color.background.neutral\')}\n\t\t\t\t/>\n\t\t\t\t<rect x="176" y="24" width="440" height="78" rx="8" fill={token(\'elevation.surface\')} />\n\t\t\t\t<rect\n\t\t\t\t\tx="198"\n\t\t\t\t\ty="44"\n\t\t\t\t\twidth="112"\n\t\t\t\t\theight="10"\n\t\t\t\t\trx="5"\n\t\t\t\t\tfill={token(\'color.background.neutral.bold\')}\n\t\t\t\t/>\n\t\t\t\t<rect\n\t\t\t\t\tx="198"\n\t\t\t\t\ty="66"\n\t\t\t\t\twidth="282"\n\t\t\t\t\theight="8"\n\t\t\t\t\trx="4"\n\t\t\t\t\tfill={token(\'color.background.neutral\')}\n\t\t\t\t/>\n\t\t\t\t<rect x="176" y="118" width="440" height="78" rx="8" fill={token(\'elevation.surface\')} />\n\t\t\t\t<path\n\t\t\t\t\td="M204 174 L270 157 L334 166 L404 138 L470 149 L540 128 L588 136"\n\t\t\t\t\tfill="none"\n\t\t\t\t\tstroke={token(\'color.border.discovery\')}\n\t\t\t\t\tstrokeWidth="6"\n\t\t\t\t\tstrokeLinecap="round"\n\t\t\t\t\tstrokeLinejoin="round"\n\t\t\t\t/>\n\t\t\t\t<circle cx="588" cy="136" r="7" fill={token(\'color.icon.discovery\')} />\n\t\t\t</svg>\n\t\t</CardMedia>\n\t);\n\treturn (\n\t\t<Card appearance="raised">\n\t\t\t{position === \'top\' && media}\n\t\t\t<CardContent>\n\t\t\t\t<CardPrimaryContent>\n\t\t\t\t\t<CardBody>\n\t\t\t\t\t\t<Text>Prototype review is ready for feedback.</Text>\n\t\t\t\t\t</CardBody>\n\t\t\t\t\t<CardFooter>\n\t\t\t\t\t\t<Text size="small" color="color.text.subtle">\n\t\t\t\t\t\t\tUpdated 2 hours ago\n\t\t\t\t\t\t</Text>\n\t\t\t\t\t</CardFooter>\n\t\t\t\t</CardPrimaryContent>\n\t\t\t</CardContent>\n\t\t\t{position === \'bottom\' && media}\n\t\t</Card>\n\t);\n}\nexport default function MediaCardExample(): React.JSX.Element {\n\treturn (\n\t\t<Stack space="space.200">\n\t\t\t<MediaCard position="top" />\n\t\t\t<MediaCard position="bottom" />\n\t\t</Stack>\n\t);\n}',
