			"import { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport { CardBody } from '@atlassian/card/card-body';\nimport { CardContent } from '@atlassian/card/card-content';\nimport { CardDescription } from '@atlassian/card/card-description';\nimport { CardHeader } from '@atlassian/card/card-header';\nimport { CardPrimaryContent } from '@atlassian/card/card-primary-content';\nimport { CardTitle } from '@atlassian/card/card-title';\nimport { CompactCard } from '@atlassian/card/compact-card';\nconst projects = [\n\t{ name: 'Atlas', description: 'Product planning · 12 active items' },\n\t{ name: 'Beacon', description: 'Customer insights · 4 active items' },\n\t{ name: 'Canvas', description: 'Design foundations · 8 active items' },\n];\nexport default function CompactProjectCollection(): React.JSX.Element {\n\treturn (\n\t\t<Stack space=\"space.100\">\n\t\t\t{projects.map(({ name, description }) => (\n\t\t\t\t<CompactCard key={name} appearance=\"flat\">\n\t\t\t\t\t<CardContent>\n\t\t\t\t\t\t<CardPrimaryContent>\n\t\t\t\t\t\t\t<CardHeader>\n\t\t\t\t\t\t\t\t<CardTitle as=\"h3\">{name}</CardTitle>\n\t\t\t\t\t\t\t\t<CardDescription>{description}</CardDescription>\n\t\t\t\t\t\t\t</CardHeader>\n\t\t\t\t\t\t\t<CardBody>\n\t\t\t\t\t\t\t\t<Text size=\"small\">Updated today</Text>\n\t\t\t\t\t\t\t</CardBody>\n\t\t\t\t\t\t</CardPrimaryContent>\n\t\t\t\t\t</CardContent>\n\t\t\t\t</CompactCard>\n\t\t\t))}\n\t\t</Stack>\n\t);\n}",
