		keywords: ['rovo', 'agent', 'actions', 'profile'],
		category: 'rovo',
		examples: [
			"import { IntlProvider } from 'react-intl';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport type { AgentDetailsWithAggData } from '@atlassian/conversation-assistant-agent/controllers/agent-details';\nimport { ActionsSection } from '@atlassian/conversation-assistant-agent/ui/ActionsSection';\nconst agent: AgentDetailsWithAggData = {\n\tid: 'release-coach',\n\tnamed_id: 'release-coach',\n\tname: 'Release coach',\n\tdescription: 'Helps teams prepare reliable releases.',\n\tcreator_type: 'SYSTEM',\n\tavailable_plugins: {},\n\tis_default: false,\n\tactor_type: 'AGENT',\n\tuser_defined_conversation_starters: null,\n\tfavourite: false,\n\tdeactivated: false,\n\tfavourite_count: 12,\n\tscenarios: [\n\t\t{\n\t\t\tid: 'release-readiness',\n\t\t\tname: 'Release readiness',\n\t\t\tscenarioVersion: 2,\n\t\t\tisDefault: true,\n\t\t\tisActive: true,\n\t\t\tisValid: { value: true },\n\t\t\tactions: [\n\t\t\t\t{\n\t\t\t\t\tactionKey: 'summarise-release-risks',\n\t\t\t\t\tname: 'Summarise release risks',\n\t\t\t\t\tdescription: 'Summarise open blockers before release.',\n\t\t\t\t\ticonUrl: '',\n\t\t\t\t\ttags: ['jira'],\n\t\t\t\t},\n\t\t\t],\n\t\t},\n\t],\n\tmcpServers: [],\n\tmcpTools: [],\n};\nexport default function AgentProfileActionsExample(): React.JSX.Element {\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Stack space=\"space.100\">\n\t\t\t\t<Text weight=\"bold\">Release coach capabilities</Text>\n\t\t\t\t<ActionsSection agent={agent} />\n\t\t\t</Stack>\n\t\t</IntlProvider>\n\t);\n}",
		],
		props: [
			{
				name: 'agent',
				type: 'AgentDetailsWithAggData',
				isRequired: true,
			},
		],
