			"import React, { useState } from 'react';\nimport { ExternalContextBrowserWrapper } from '@atlassian/conversation-assistant-external-context/main';\ntype Project = { id: string; name: string; key: string };\nconst projects: Project[] = [\n\t{ id: 'project-1', name: 'Customer onboarding', key: 'ONB' },\n\t{ id: 'project-2', name: 'Mobile experience', key: 'MOB' },\n];\nexport default function ProjectContextBrowserExample(): React.JSX.Element {\n\tconst [isOpen, setIsOpen] = useState(false);\n\tconst [selectedProject, setSelectedProject] = useState<Project | null>(null);\n\treturn (\n\t\t<section aria-label=\"Prompt context\">\n\t\t\t{selectedProject ? (\n\t\t\t\t<p role=\"status\">\n\t\t\t\t\tSelected project: {selectedProject.name} ({selectedProject.key}).\n\t\t\t\t</p>\n\t\t\t) : null}\n\t\t\t<button type=\"button\" onClick={() => setIsOpen((open) => !open)}>\n\t\t\t\t{isOpen ? 'Close project browser' : 'Add project context'}\n\t\t\t</button>\n\t\t\t{isOpen ? (\n\t\t\t\t<ExternalContextBrowserWrapper>\n\t\t\t\t\t<section aria-labelledby=\"project-browser-heading\">\n\t\t\t\t\t\t<h2 id=\"project-browser-heading\">Choose a project</h2>\n\t\t\t\t\t\t<p>Project details will be included with your prompt.</p>\n\t\t\t\t\t\t<ul>\n\t\t\t\t\t\t\t{projects.map((project) => (\n\t\t\t\t\t\t\t\t<li key={project.id}>\n\t\t\t\t\t\t\t\t\t<button\n\t\t\t\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\t\t\t\tonClick={() => {\n\t\t\t\t\t\t\t\t\t\t\tsetSelectedProject(project);\n\t\t\t\t\t\t\t\t\t\t\tsetIsOpen(false);\n\t\t\t\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\t\t\t>\n\t\t\t\t\t\t\t\t\t\t{project.name} ({project.key})\n\t\t\t\t\t\t\t\t\t</button>\n\t\t\t\t\t\t\t\t</li>\n\t\t\t\t\t\t\t))}\n\t\t\t\t\t\t</ul>\n\t\t\t\t\t</section>\n\t\t\t\t</ExternalContextBrowserWrapper>\n\t\t\t) : null}\n\t\t</section>\n\t);\n}",
