			"/**\n * @jsxRuntime classic\n * @jsx jsx\n */\nimport { IntlProvider } from 'react-intl';\nimport type { DocNode } from '@atlaskit/adf-schema/doc';\nimport { cssMap, jsx } from '@atlaskit/css';\nimport { Box } from '@atlaskit/primitives/compiled/box';\nimport { token } from '@atlaskit/tokens';\nimport type { ActionKeys } from '@atlassian/conversation-assistant-message-actions-api/constants';\nimport type {\n\tActionRendererFor,\n\tActionRendererKeyToPayload,\n\tActionWith,\n} from '@atlassian/conversation-assistant-message-actions-api/types';\nimport { ConfluencePageCreateAction } from '@atlassian/conversation-assistant-message-actions/controllers/confluence-page-create';\nconst styles = cssMap({\n\troot: {\n\t\twidth: '500px',\n\t\tpaddingTop: token('space.400'),\n\t\tpaddingRight: token('space.200'),\n\t\tpaddingBottom: token('space.200'),\n\t\tpaddingLeft: token('space.200'),\n\t\tmargin: '0 auto',\n\t},\n});\nconst action: ActionWith<ActionRendererKeyToPayload[typeof ActionKeys.ConfluencePageCreate]> = {\n\tkey: 'confluence-page-create',\n\tinvocationId: '123',\n\tdata: {\n\t\tname: 'My Page',\n\t\tfolder: '123',\n\t\tcontent: JSON.stringify({\n\t\t\tversion: 1,\n\t\t\ttype: 'doc',\n\t\t\tcontent: [\n\t\t\t\t{\n\t\t\t\t\ttype: 'paragraph',\n\t\t\t\t\tcontent: [\n\t\t\t\t\t\t{\n\t\t\t\t\t\t\ttype: 'text',\n\t\t\t\t\t\t\ttext: 'Hello, this is a page created by the Confluence Page Create action.',\n\t\t\t\t\t\t},\n\t\t\t\t\t],\n\t\t\t\t},\n\t\t\t],\n\t\t} as DocNode),\n\t\textraInputs: {\n\t\t\tcontentTypePath: 'page',\n\t\t\trepresentation: 'atlas_doc_format',\n\t\t},\n\t},\n};\nconst defaultProps = {} as ActionRendererFor<typeof ActionKeys.ConfluencePageCreate>;\nexport default function (): JSX.Element {\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Box xcss={styles.root}>\n\t\t\t\t<ConfluencePageCreateAction\n\t\t\t\t\t{...defaultProps}\n\t\t\t\t\tactions={[action]}\n\t\t\t\t\tcloudId=\"\"\n\t\t\t\t\tonCustomDataConfirm={() => Promise.resolve()}\n\t\t\t\t\tonCancel={() => Promise.resolve()}\n\t\t\t\t\tgetStatus={() => 'planned'}\n\t\t\t\t\tgetReadonly={() => false}\n\t\t\t\t\tproductKey=\"\"\n\t\t\t\t\tmessageId=\"test-message-id\"\n\t\t\t\t/>\n\t\t\t</Box>\n\t\t</IntlProvider>\n\t);\n}",
