			"import React, { useState } from 'react';\nimport { RelayEnvironmentProvider } from 'react-relay';\nimport type { Environment } from 'relay-runtime';\nimport { Anchor } from '@atlaskit/primitives/compiled/anchor';\nimport { RovoDevPrSubscription } from '@atlassian/conversation-assistant-message-actions/controllers/rovodev-pr-status/RovoDevPrSubscription';\n/** This export renders null; the host owns the visible waiting and PR-link states. */\nexport const SessionPullRequestSubscription = ({\n\tenvironment,\n\tsessionAri,\n}: {\n\tenvironment: Environment;\n\tsessionAri: string;\n}): React.JSX.Element => {\n\tconst [prUrl, setPrUrl] = useState<string | null>(null);\n\treturn (\n\t\t<RelayEnvironmentProvider environment={environment}>\n\t\t\t<RovoDevPrSubscription sessionAri={sessionAri} onPrUpdate={setPrUrl} />\n\t\t\t{prUrl ? (\n\t\t\t\t<Anchor href={prUrl}>View pull request</Anchor>\n\t\t\t) : (\n\t\t\t\t<p role=\"status\">Waiting for this session to raise a pull request.</p>\n\t\t\t)}\n\t\t</RelayEnvironmentProvider>\n\t);\n};",
