			"import { RelayEnvironmentProvider } from 'react-relay';\nimport type { Environment } from 'relay-runtime';\nimport { RovoDevSessionPrLink } from '@atlassian/conversation-assistant-message-actions/controllers/rovodev-pr-status/RovoDevSessionPrLink';\n/** The environment and session ARI must come from the authenticated session host. */\nexport const SessionPullRequestLink = ({\n\tenvironment,\n\tsessionAri,\n}: {\n\tenvironment: Environment;\n\tsessionAri: string;\n}): React.JSX.Element => (\n\t<RelayEnvironmentProvider environment={environment}>\n\t\t<section aria-labelledby=\"session-pull-request-heading\">\n\t\t\t<h2 id=\"session-pull-request-heading\">Rovo Dev pull request</h2>\n\t\t\t<p>The link appears when this session has raised a pull request.</p>\n\t\t\t<RovoDevSessionPrLink sessionAri={sessionAri} />\n\t\t</section>\n\t</RelayEnvironmentProvider>\n);",
