				name: 'formatMessage',
				type: '{ (this: void, descriptor: MessageDescriptor, values?: Record<string, PrimitiveType | FormatXMLElementFn<string, string>>, opts?: Options): string; (this: void, descriptor: MessageDescriptor, values?: Record<...>, opts?: Options): React.ReactNode[]; }',
				isRequired: true,
