			"import { IntlProvider } from 'react-intl';\nimport Button from '@atlaskit/button/default/button';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport type { SideNavModalItem } from '@atlassian/conversation-assistant-ui-components/ui/side-nav-modal/modal';\nimport {\n\tSideNavModalProvider,\n\tuseSideNavModal,\n} from '@atlassian/conversation-assistant-ui-components/ui/side-nav-modal/side-nav-modal-provider';\nconst SETTINGS_ITEMS: SideNavModalItem[] = [\n\t{\n\t\tid: 'response-style',\n\t\tlabel: 'Response style',\n\t\tsearchLabel: 'Response style',\n\t\tcontentHeader: 'Response style',\n\t\tcontent: () => <Text>Choose concise, balanced, or detailed responses for this workspace.</Text>,\n\t},\n\t{\n\t\tid: 'connected-apps',\n\t\tlabel: 'Connected apps',\n\t\tsearchLabel: 'Connected apps and sources',\n\t\tcontentHeader: 'Connected apps',\n\t\tcontent: ({ pushSubscreen }) => (\n\t\t\t<Stack space=\"space.100\">\n\t\t\t\t<Text>Choose which connected sources Rovo can use in this workspace.</Text>\n\t\t\t\t<Button\n\t\t\t\t\tonClick={() =>\n\t\t\t\t\t\tpushSubscreen({\n\t\t\t\t\t\t\tbackLabel: 'Connected apps',\n\t\t\t\t\t\t\tcontent: (\n\t\t\t\t\t\t\t\t<Text>Review access for each connected source with your workspace admin.</Text>\n\t\t\t\t\t\t\t),\n\t\t\t\t\t\t})\n\t\t\t\t\t}\n\t\t\t\t>\n\t\t\t\t\tReview source access\n\t\t\t\t</Button>\n\t\t\t</Stack>\n\t\t),\n\t},\n];\nfunction SettingsEntryPoint(): React.JSX.Element {\n\tconst { open } = useSideNavModal();\n\treturn (\n\t\t<Stack space=\"space.100\">\n\t\t\t<Button\n\t\t\t\tonClick={() =>\n\t\t\t\t\topen({\n\t\t\t\t\t\ttitle: 'Rovo settings',\n\t\t\t\t\t\tsearchPlaceholder: 'Search settings',\n\t\t\t\t\t\tnavAriaLabel: 'Rovo settings sections',\n\t\t\t\t\t\tdefaultSelectedId: 'response-style',\n\t\t\t\t\t\tsurface: 'chat-toolbar',\n\t\t\t\t\t})\n\t\t\t\t}\n\t\t\t>\n\t\t\t\tOpen Rovo settings\n\t\t\t</Button>\n\t\t\t<Text>Settings are shared by every entry point inside this chat surface.</Text>\n\t\t</Stack>\n\t);\n}\nexport default function SideNavModalProviderExample(): React.JSX.Element {\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t{/* Keep this inside the host's conversation analytics provider. */}\n\t\t\t<SideNavModalProvider items={SETTINGS_ITEMS}>\n\t\t\t\t<SettingsEntryPoint />\n\t\t\t</SideNavModalProvider>\n\t\t</IntlProvider>\n\t);\n}",
