		examples: [
			"import React, { useState } from 'react';\nimport { IntlProvider } from 'react-intl';\nimport { DiProvider, injectable } from 'react-magnetic-di';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport { usePublish } from '@atlaskit/rovo-triggers/main';\nimport { useAnalytics } from '@atlassian/conversation-assistant-instrumentation/controllers/analytics';\nimport { AwaitingPlanAcceptanceView } from '@atlassian/conversation-assistant/ui/task-progress-view/AwaitingPlanAcceptanceView';\nimport { AwaitingUserResponseView } from '@atlassian/conversation-assistant/ui/task-progress-view/AwaitingUserResponseView';\nconst mockUsePublish = () => () => {};\nconst mockUseAnalytics = () => ({ sendAnalyticsEvent: () => {} });\nexport default function TaskProgressWaitStatesExample(): React.JSX.Element {\n\tconst [stoppedTask, setStoppedTask] = useState<string | null>(null);\n\treturn (\n\t\t<DiProvider\n\t\t\tuse={[injectable(usePublish, mockUsePublish), injectable(useAnalytics, mockUseAnalytics)]}\n\t\t>\n\t\t\t<IntlProvider locale=\"en\">\n\t\t\t\t<Stack space=\"space.200\">\n\t\t\t\t\t<Stack space=\"space.100\">\n\t\t\t\t\t\t<Text weight=\"semibold\">Plan awaiting approval</Text>\n\t\t\t\t\t\t{stoppedTask === 'plan' ? (\n\t\t\t\t\t\t\t<Text aria-live=\"polite\">Plan task stopped by the host.</Text>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<AwaitingPlanAcceptanceView\n\t\t\t\t\t\t\t\tconversationId=\"example-conversation\"\n\t\t\t\t\t\t\t\tactionInvocationId=\"plan-invocation\"\n\t\t\t\t\t\t\t\tonStopTask={() => setStoppedTask('plan')}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</Stack>\n\t\t\t\t\t<Stack space=\"space.100\">\n\t\t\t\t\t\t<Text weight=\"semibold\">Task waiting for an answer</Text>\n\t\t\t\t\t\t{stoppedTask === 'question' ? (\n\t\t\t\t\t\t\t<Text aria-live=\"polite\">Question task stopped by the host.</Text>\n\t\t\t\t\t\t) : (\n\t\t\t\t\t\t\t<AwaitingUserResponseView\n\t\t\t\t\t\t\t\tconversationId=\"example-conversation\"\n\t\t\t\t\t\t\t\tactionInvocationId=\"question-invocation\"\n\t\t\t\t\t\t\t\tonStopTask={() => setStoppedTask('question')}\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t)}\n\t\t\t\t\t</Stack>\n\t\t\t\t</Stack>\n\t\t\t</IntlProvider>\n\t\t</DiProvider>\n\t);\n}",
		],
		props: [
			{
				name: 'actionInvocationId',
				type: 'string',
				isRequired: true,
			},
			{
				name: 'conversationId',
				type: 'string',
				isRequired: true,
			},
			{
				name: 'onStopTask',
				type: '() => void',
			},
		],
