			"import { IntlProvider } from 'react-intl';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport { BaseConfluenceObjectFinalizePopupInner } from '@atlassian/rovo-platform-ui-components/confluence-object-finalize-popup';\nimport type { BaseConfluenceObjectFinalizePopupProps } from '@atlassian/rovo-platform-ui-components/confluence-object-finalize-popup/types';\ntype FinalizeResult = Awaited<\n\tReturnType<BaseConfluenceObjectFinalizePopupProps['finalizeSmartCreate']>\n>;\ntype HostFinalizeProps = Omit<BaseConfluenceObjectFinalizePopupProps, 'finalizeSmartCreate'> & {\n\tfinalizeSmartCreate: BaseConfluenceObjectFinalizePopupProps['finalizeSmartCreate'];\n\tonPersisted: (result: FinalizeResult) => void;\n};\n/** The host supplies tenant data, API callbacks, analytics, and authorization. */\nexport default function ConfluenceObjectFinalizePopupExample({\n\tfinalizeSmartCreate,\n\tonPersisted,\n\t...hostProps\n}: HostFinalizeProps): React.JSX.Element {\n\tconst finalizeAndHandlePersistedResult: HostFinalizeProps['finalizeSmartCreate'] = async (\n\t\tparams,\n\t) => {\n\t\tconst result = await finalizeSmartCreate(params);\n\t\tonPersisted(result);\n\t\treturn result;\n\t};\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Stack space=\"space.100\">\n\t\t\t\t<Text>\n\t\t\t\t\tUse the persisted result for host navigation or follow-up UI; do not construct a URL from\n\t\t\t\t\tthe selected title.\n\t\t\t\t</Text>\n\t\t\t\t<BaseConfluenceObjectFinalizePopupInner\n\t\t\t\t\t{...hostProps}\n\t\t\t\t\tfinalizeSmartCreate={finalizeAndHandlePersistedResult}\n\t\t\t\t/>\n\t\t\t</Stack>\n\t\t</IntlProvider>\n\t);\n}",
