			"import React, { useState } from 'react';\nimport { IntlProvider } from 'react-intl';\nimport Button from '@atlaskit/button/default/button';\nimport { cssMap } from '@atlaskit/css';\nimport Heading from '@atlaskit/heading/heading';\nimport { Box } from '@atlaskit/primitives/compiled/box';\nimport { Inline } from '@atlaskit/primitives/compiled/inline';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { token } from '@atlaskit/tokens';\nimport { SessionList } from '@atlassian/rovo-platform-ui-components/session-list/SessionList';\nimport { SessionListActionMenu } from '@atlassian/rovo-platform-ui-components/session-list/SessionListActionMenu';\nimport { SessionListEmpty } from '@atlassian/rovo-platform-ui-components/session-list/SessionListEmpty';\nimport { SessionListError } from '@atlassian/rovo-platform-ui-components/session-list/SessionListError';\nimport { SessionListFooter } from '@atlassian/rovo-platform-ui-components/session-list/SessionListFooter';\nimport { SessionListItem } from '@atlassian/rovo-platform-ui-components/session-list/SessionListItem';\nimport { SessionListLoading } from '@atlassian/rovo-platform-ui-components/session-list/SessionListLoading';\nconst styles = cssMap({\n\twrapper: {\n\t\twidth: '100%',\n\t\tmaxWidth: '1000px',\n\t\tmarginInlineStart: 'auto',\n\t\tmarginInlineEnd: 'auto',\n\t\tpaddingTop: token('space.400'),\n\t\tpaddingBottom: token('space.400'),\n\t\tpaddingInlineStart: token('space.200'),\n\t\tpaddingInlineEnd: token('space.200'),\n\t},\n\tcompactList: {\n\t\twidth: '320px',\n\t\tmaxWidth: '100%',\n\t},\n});\nexport default function (): React.JSX.Element {\n\tconst [status, setStatus] = useState<'WORKING' | 'INPUT_REQUIRED' | undefined>('WORKING');\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Stack xcss={styles.wrapper} space=\"space.400\">\n\t\t\t\t<Inline space=\"space.100\">\n\t\t\t\t\t<Button onClick={() => setStatus('WORKING')}>Working</Button>\n\t\t\t\t\t<Button onClick={() => setStatus('INPUT_REQUIRED')}>Needs input</Button>\n\t\t\t\t\t<Button onClick={() => setStatus(undefined)}>Unread</Button>\n\t\t\t\t</Inline>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Compact working session</Heading>\n\t\t\t\t\t<Box role=\"list\" xcss={styles.compactList}>\n\t\t\t\t\t\t<SessionListItem\n\t\t\t\t\t\t\tsession={{\n\t\t\t\t\t\t\t\tid: 'compact-working',\n\t\t\t\t\t\t\t\ttitle: 'Build the release summary',\n\t\t\t\t\t\t\t\tstate: status,\n\t\t\t\t\t\t\t\tdisplayAgent: { id: 'planning-agent', name: 'Planning agent' },\n\t\t\t\t\t\t\t\tconversationChannel: { name: 'Build the release summary', readStatus: false },\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tonActivate={() => {}}\n\t\t\t\t\t\t\tactions={\n\t\t\t\t\t\t\t\t<SessionListActionMenu name=\"Build the release summary\" onDelete={() => {}} />\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Compact linked context</Heading>\n\t\t\t\t\t<Box role=\"list\" xcss={styles.compactList}>\n\t\t\t\t\t\t<SessionListItem\n\t\t\t\t\t\t\tsession={{\n\t\t\t\t\t\t\t\tid: 'compact-linked',\n\t\t\t\t\t\t\t\tdisplayAgent: { id: 'planning-agent', name: 'Planning agent' },\n\t\t\t\t\t\t\t\ttitle: 'Review the quarterly customer development plan',\n\t\t\t\t\t\t\t\tstate: status,\n\t\t\t\t\t\t\t\tconversationChannel: {\n\t\t\t\t\t\t\t\t\tname: 'Review the quarterly customer development plan',\n\t\t\t\t\t\t\t\t\treadStatus: false,\n\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\tcontexts: [\n\t\t\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\t\t\tid: 'linked-plan',\n\t\t\t\t\t\t\t\t\t\tlabel: 'Quarterly customer development work graph',\n\t\t\t\t\t\t\t\t\t\ttype: 'confluence',\n\t\t\t\t\t\t\t\t\t\turl: 'https://example.atlassian.net/wiki/pages/123',\n\t\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\t],\n\t\t\t\t\t\t\t\tlastStateChangeAt: Date.now() - 300_000,\n\t\t\t\t\t\t\t}}\n\t\t\t\t\t\t\tonActivate={() => {}}\n\t\t\t\t\t\t\tactions={<SessionListActionMenu name=\"Review the plan\" onDelete={() => {}} />}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Populated</Heading>\n\t\t\t\t\t<SessionList\n\t\t\t\t\t\tariaLabel=\"Agent sessions\"\n\t\t\t\t\t\tonOpenConversation={() => {}}\n\t\t\t\t\t\tsessions={[\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tid: 'full',\n\t\t\t\t\t\t\t\tconversationChannel: {\n\t\t\t\t\t\t\t\t\tid: 'conversation-full',\n\t\t\t\t\t\t\t\t\tname: 'Prepare the quarterly review',\n\t\t\t\t\t\t\t\t\treadStatus: false,\n\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\tstate: 'INPUT_REQUIRED',\n\t\t\t\t\t\t\t\tdisplayAgent: { id: 'planning-agent', name: 'Planning agent' },\n\t\t\t\t\t\t\t\tcontexts: [{ id: 'DS-204', label: 'DS-204', type: 'jira' }],\n\t\t\t\t\t\t\t\tlastStateChangeAt: Date.now() - 300_000,\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tid: 'in-progress',\n\t\t\t\t\t\t\t\tconversationChannel: {\n\t\t\t\t\t\t\t\t\tid: 'conversation-in-progress',\n\t\t\t\t\t\t\t\t\tname: 'Build the release summary',\n\t\t\t\t\t\t\t\t\treadStatus: false,\n\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t\tstate: status,\n\t\t\t\t\t\t\t\tdisplayAgent: { id: 'planning-agent', name: 'Planning agent' },\n\t\t\t\t\t\t\t\tcontexts: [{ id: 'DS-205', label: 'DS-205', type: 'jira' }],\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tid: 'unread',\n\t\t\t\t\t\t\t\tconversationChannel: {\n\t\t\t\t\t\t\t\t\tid: 'conversation-unread',\n\t\t\t\t\t\t\t\t\tname: 'Review the updated plan',\n\t\t\t\t\t\t\t\t\treadStatus: false,\n\t\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t\t{\n\t\t\t\t\t\t\t\tid: 'sparse',\n\t\t\t\t\t\t\t\tconversationChannel: { name: 'Summarize the planning notes' },\n\t\t\t\t\t\t\t},\n\t\t\t\t\t\t]}\n\t\t\t\t\t/>\n\t\t\t\t\t<SessionListFooter state=\"end\" label=\"You have reached the end\" />\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Loading</Heading>\n\t\t\t\t\t<SessionListLoading label=\"Loading items\" rowCount={3} />\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Empty</Heading>\n\t\t\t\t\t<Box>\n\t\t\t\t\t\t<SessionListEmpty\n\t\t\t\t\t\t\theader=\"Nothing needs your input\"\n\t\t\t\t\t\t\tdescription=\"When an agent needs a decision or confirmation from you, it'll show up here.\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Error with retry</Heading>\n\t\t\t\t\t<Box>\n\t\t\t\t\t\t<SessionListError\n\t\t\t\t\t\t\theader=\"We couldn't load this page\"\n\t\t\t\t\t\t\tdescription=\"Check your connection and try again.\"\n\t\t\t\t\t\t\tretryLabel=\"Try again\"\n\t\t\t\t\t\t\tonRetry={() => {}}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t</Stack>\n\t\t\t\t<Stack space=\"space.150\">\n\t\t\t\t\t<Heading size=\"medium\">Error without retry</Heading>\n\t\t\t\t\t<Box>\n\t\t\t\t\t\t<SessionListError\n\t\t\t\t\t\t\theader=\"We couldn't load this page\"\n\t\t\t\t\t\t\tdescription=\"Retrying isn't available for this page.\"\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t</Stack>\n\t\t\t</Stack>\n\t\t</IntlProvider>\n\t);\n}",
