			"import React, { useState } from 'react';\nimport { IntlProvider } from 'react-intl';\nimport Button from '@atlaskit/button/default/button';\nimport { Box } from '@atlaskit/primitives/compiled/box';\nimport { Inline } from '@atlaskit/primitives/compiled/inline';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { SmartContextRecommendationsModal } from '@atlassian/rovo-spaces/ui/SmartContextRecommendationsModal';\nimport type { SmartContextRecommendationType } from '@atlassian/rovo-spaces/ui/SmartContextRecommendationsModal/types';\nimport { DUMMY_CHAT_RECOMMENDATIONS } from '../src/ui/smart-context-recommendations-modal/__tests__/__fixtures__/dummyChatRecommendations';\nimport { DUMMY_LINK_RECOMMENDATIONS } from '../src/ui/smart-context-recommendations-modal/__tests__/__fixtures__/dummyLinkRecommendations';\nexport default function SmartContextRecommendationsModalExample(): React.JSX.Element {\n\tconst [type, setType] = useState<SmartContextRecommendationType>('chat');\n\tconst [isOpen, setIsOpen] = useState(true);\n\tconst recommendations = type === 'chat' ? DUMMY_CHAT_RECOMMENDATIONS : DUMMY_LINK_RECOMMENDATIONS;\n\tconst [selectedRecommendationIds, setSelectedRecommendationIds] = useState(\n\t\trecommendations.map((recommendation) => recommendation.recommendationId),\n\t);\n\tconst openModal = (nextType: SmartContextRecommendationType) => {\n\t\tconst nextRecommendations =\n\t\t\tnextType === 'chat' ? DUMMY_CHAT_RECOMMENDATIONS : DUMMY_LINK_RECOMMENDATIONS;\n\t\tsetType(nextType);\n\t\tsetSelectedRecommendationIds(\n\t\t\tnextRecommendations.map((recommendation) => recommendation.recommendationId),\n\t\t);\n\t\tsetIsOpen(true);\n\t};\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Box padding=\"space.300\">\n\t\t\t\t<Stack space=\"space.200\">\n\t\t\t\t\t<Inline space=\"space.100\">\n\t\t\t\t\t\t<Button appearance=\"primary\" onClick={() => openModal('chat')}>\n\t\t\t\t\t\t\tOpen add chats modal\n\t\t\t\t\t\t</Button>\n\t\t\t\t\t\t<Button onClick={() => openModal('link')}>Open add links modal</Button>\n\t\t\t\t\t</Inline>\n\t\t\t\t\t<SmartContextRecommendationsModal\n\t\t\t\t\t\tisOpen={isOpen}\n\t\t\t\t\t\trecommendationType={type}\n\t\t\t\t\t\trecommendations={recommendations}\n\t\t\t\t\t\tselectedRecommendationIds={selectedRecommendationIds}\n\t\t\t\t\t\tonSelectionChange={setSelectedRecommendationIds}\n\t\t\t\t\t\tonClose={() => setIsOpen(false)}\n\t\t\t\t\t\tonSubmit={() => setIsOpen(false)}\n\t\t\t\t\t/>\n\t\t\t\t</Stack>\n\t\t\t</Box>\n\t\t</IntlProvider>\n\t);\n}",
