			"import { cssMap } from '@atlaskit/css';\nimport FireIcon from '@atlaskit/icon-lab/core/fire';\nimport Lozenge from '@atlaskit/lozenge/new/lozenge';\nimport { Box } from '@atlaskit/primitives/compiled/box';\nimport { type AgentCardFooterProps } from '@atlassian/studio-browse-kit/agent-card';\nimport { AgentCardRelay } from '@atlassian/studio-browse-kit/agent-card-relay';\nimport { CardMetadata } from '@atlassian/studio-browse-kit/ui/card-metadata';\nimport {\n\tCLOUD_ID,\n\tConnectedExample,\n\tExampleFrame,\n\tExampleAgentCover,\n\tagents,\n} from '../examples-utils/support';\nconst styles = cssMap({ card: { width: '280px', maxWidth: '100%' } });\nconst PopularMetadata = ({ testId }: AgentCardFooterProps): React.JSX.Element => (\n\t<CardMetadata testId={testId}>\n\t\t<Lozenge appearance=\"accent-yellow\" iconBefore={FireIcon}>\n\t\t\tPopular\n\t\t</Lozenge>\n\t</CardMetadata>\n);\nexport function AgentCardWithActionsPreview(): React.JSX.Element {\n\tconst agentData = [\n\t\t{\n\t\t\t...agents[0],\n\t\t\tcreatorName: 'Software Engineering',\n\t\t\tdescription: 'Ensures written code adheres to standards.',\n\t\t},\n\t];\n\treturn (\n\t\t<ExampleFrame>\n\t\t\t<ConnectedExample agentData={agentData}>\n\t\t\t\t{({ agentRefs }) => (\n\t\t\t\t\t<Box xcss={styles.card}>\n\t\t\t\t\t\t<AgentCardRelay\n\t\t\t\t\t\t\tagentRef={agentRefs[0]}\n\t\t\t\t\t\t\tcloudId={CLOUD_ID}\n\t\t\t\t\t\t\tonClick={() => {}}\n\t\t\t\t\t\t\tonChat={() => {}}\n\t\t\t\t\t\t\tslots={{ cover: ExampleAgentCover, metadata: PopularMetadata }}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</Box>\n\t\t\t\t)}\n\t\t\t</ConnectedExample>\n\t\t</ExampleFrame>\n\t);\n}\nexport default AgentCardWithActionsPreview;",
