			"import { IntlProvider } from 'react-intl';\nimport { cssMap } from '@atlaskit/css';\nimport AiSparkleIcon from '@atlaskit/icon/core/ai-sparkle';\nimport { Box } from '@atlaskit/primitives/compiled/box';\nimport { Stack } from '@atlaskit/primitives/compiled/stack';\nimport { Text } from '@atlaskit/primitives/compiled/text';\nimport { HeroCardSkeleton } from '@atlassian/studio-browse-kit/hero-card-skeleton';\nimport { IntroLayout } from '@atlassian/studio-browse-kit/intro-layout';\nimport { RovoAgentCardCover } from '@atlassian/studio-browse-kit/rovo-agent-card-cover';\nimport { Card } from '@atlassian/studio-browse-kit/ui/card';\nimport { CardAvatarFrame } from '@atlassian/studio-browse-kit/ui/card-avatar-frame';\nimport { CardContent } from '@atlassian/studio-browse-kit/ui/card-content';\nimport { CardFooter } from '@atlassian/studio-browse-kit/ui/card-footer';\nimport { CosmosBackground } from '@atlassian/studio-browse-kit/ui/cosmos-background';\nimport { CosmosEffect } from '@atlassian/studio-browse-kit/ui/cosmos-effect';\nimport { HeroCardList } from '@atlassian/studio-browse-kit/ui/hero-card-list';\nimport { RovoAgentAvatar } from '@atlassian/studio-browse-kit/ui/rovo-agent-avatar';\nimport { ToolList } from '@atlassian/studio-browse-kit/ui/tool-list';\ntype ToolItems = React.ComponentProps<typeof ToolList>['items'];\n/** Pass tool icon URLs from the host's actual app catalog. */\nconst styles = cssMap({ container: { position: 'relative', minHeight: '80px' } });\nexport default function BrowseKitPrimitives({\n\ttools,\n\tonOpenAgent,\n}: {\n\ttools: ToolItems;\n\tonOpenAgent: () => void;\n}): React.JSX.Element {\n\treturn (\n\t\t<IntlProvider locale=\"en\">\n\t\t\t<Stack space=\"space.400\">\n\t\t\t\t<IntroLayout\n\t\t\t\t\ticon={<AiSparkleIcon label=\"\" />}\n\t\t\t\t\ttitle=\"Recommended for your team\"\n\t\t\t\t\tdescription=\"Browse assistants and templates for common work.\"\n\t\t\t\t>\n\t\t\t\t\t<HeroCardList title=\"Featured agents\">\n\t\t\t\t\t\t<Card ariaLabel=\"Open Release readiness checker\" onClick={onOpenAgent}>\n\t\t\t\t\t\t\t<CardContent\n\t\t\t\t\t\t\t\tname=\"Release readiness checker\"\n\t\t\t\t\t\t\t\tdescription=\"Surfaces delivery risks before a release.\"\n\t\t\t\t\t\t\t/>\n\t\t\t\t\t\t</Card>\n\t\t\t\t\t</HeroCardList>\n\t\t\t\t</IntroLayout>\n\t\t\t\t<HeroCardSkeleton />\n\t\t\t\t<Card ariaLabel=\"Open Rovo\" onClick={onOpenAgent}>\n\t\t\t\t\t<RovoAgentCardCover name=\"Rovo\" />\n\t\t\t\t\t<CardContent name=\"Rovo\" description=\"Finds useful knowledge across your work.\" />\n\t\t\t\t\t<CardFooter>\n\t\t\t\t\t\t<Text size=\"small\">Available in this workspace</Text>\n\t\t\t\t\t</CardFooter>\n\t\t\t\t</Card>\n\t\t\t\t<CardAvatarFrame name=\"Unavailable agent\" isHexagon />\n\t\t\t\t<RovoAgentAvatar name=\"Rovo\" />\n\t\t\t\t<CosmosEffect>\n\t\t\t\t\t<Box xcss={styles.container}>\n\t\t\t\t\t\t<CosmosBackground enableReflection={false} />\n\t\t\t\t\t</Box>\n\t\t\t\t</CosmosEffect>\n\t\t\t\t<ToolList items={tools} size=\"small\" />\n\t\t\t</Stack>\n\t\t</IntlProvider>\n\t);\n}",
