		examples: [
			"import React, { useState } from 'react';\nimport Button from '@atlaskit/button/default/button';\nimport { Popup } from '@atlaskit/popup/popup';\nimport Tooltip from '@atlaskit/tooltip/Tooltip';\nimport { AtlassianSwitcherLoader as AtlassianSwitcher } from '@atlassian/switcher/loaders';\nimport AtlassianSwitcherPrefetchTrigger from '@atlassian/switcher/prefetch-trigger';\nimport { SwitchToTooltipText } from '@atlassian/switcher/switch-to-tooltip-text';\ntype PrefetchSwitcherProps = {\n\t/** The active Atlassian site cloud ID supplied by the host. */\n\tcloudId: string;\n};\n/**\n * Prefetches switcher data on pointer hover or keyboard focus before the user opens the popup.\n *\n * The host application must configure authenticated App Switcher BFF/service requests and provide\n * its analytics client. Pass the current site's real cloud ID to this component.\n */\nexport default function PrefetchSwitcher({ cloudId }: PrefetchSwitcherProps): React.JSX.Element {\n\tconst [isOpen, setIsOpen] = useState(false);\n\treturn (\n\t\t<Popup\n\t\t\tisOpen={isOpen}\n\t\t\tonClose={() => setIsOpen(false)}\n\t\t\tplacement=\"bottom-start\"\n\t\t\tshouldRenderToParent\n\t\t\tcontent={() => <AtlassianSwitcher product=\"jira\" cloudId={cloudId} />}\n\t\t\ttrigger={({ ref, ...triggerProps }) => (\n\t\t\t\t<AtlassianSwitcherPrefetchTrigger product=\"jira\" cloudId={cloudId}>\n\t\t\t\t\t<Tooltip content={SwitchToTooltipText}>\n\t\t\t\t\t\t<Button\n\t\t\t\t\t\t\t{...triggerProps}\n\t\t\t\t\t\t\tref={ref}\n\t\t\t\t\t\t\ttype=\"button\"\n\t\t\t\t\t\t\taria-expanded={isOpen}\n\t\t\t\t\t\t\tonClick={() => setIsOpen(!isOpen)}\n\t\t\t\t\t\t>\n\t\t\t\t\t\t\tOpen app switcher\n\t\t\t\t\t\t</Button>\n\t\t\t\t\t</Tooltip>\n\t\t\t\t</AtlassianSwitcherPrefetchTrigger>\n\t\t\t)}\n\t\t/>\n\t);\n}",
		],
		props: [],
